UIWelderSmokeEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,300);this.particleClass=UIWelderSmokeParticle;this.makeParticles();this.minParticleSpeed.setTo(UIConstants.WELDER_SMOKE_MIN_X_SPEED,UIConstants.WELDER_SMOKE_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.WELDER_SMOKE_MAX_X_SPEED,UIConstants.WELDER_SMOKE_MAX_Y_SPEED);this.particleDrag.setTo(10,10);this.setAlpha(0.5,0.7);this.setRotation(0,0);this.minParticleScale=0.9;this.maxParticleScale=1.1;this.gravity=0;this.emitterPointsOld=null;this.emitterPointsNew=null;this.tankIcon=null;this.kill();this.visible=false;};UIWelderSmokeEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIWelderSmokeEmitter.prototype.constructor=UIWelderSmokeEmitter;UIWelderSmokeEmitter.prototype.update=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);UIWelderSmokeParticle.updateSpark(this.game);if(this.countLiving()==0){this.kill();this.visible=false;}};UIWelderSmokeEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIWelderSmokeEmitter.prototype.spawn=function(tankIcon,emitterPointsOld,emitterPointsNew){this.revive();this.emitterPointsOld=emitterPointsOld;this.emitterPointsNew=emitterPointsNew;UIWelderSmokeParticle.setSpawnPoints(tankIcon,this.emitterPointsOld,this.emitterPointsNew);this.flow(UIConstants.GARAGE_WELD_PARTICLE_TIME,16,5,UIConstants.GARAGE_WELD_SMOKE_TIME/16*5);};UIWelderSmokeEmitter.prototype.remove=function(){this.on=false;};UIWelderSmokeEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};